"""ESPHome Light: tests generated by `openbridge partner new`. They pass against the emulator on day one;
run them again with the real transport before recording hardware evidence."""
import json
import unittest

from src.adapters.esphome_light import (EsphomeLight, EsphomeLightBlocked, EsphomeLightError,
                                             EsphomeLightTransport, _host_allowed, _parse_brightness, _parse_power)
from src.adapters.esphome_light_emulator import EsphomeLightEmulator
from src.fabric.esphome_light_ingest import ingest_esphome_light
from src.fabric.registry import Registry


class EsphomeLightTests(unittest.TestCase):
    def setUp(self):
        self.emu = EsphomeLightEmulator()
        self.dev = EsphomeLight(self.emu)

    def test_facts(self):
        names = {f['name']: f['value'] for f in self.dev.facts()}
        self.assertEqual(names['brightness'], 50)

    def test_setting_is_read_back_and_undone_exactly(self):
        r = self.dev.set_reversible('brightness', 80)
        self.assertEqual((r['before'], r['after'], r['verified']), (50, 80, True))
        self.assertTrue(self.dev.undo('brightness')['exact'])
        self.assertEqual(self.emu.state['brightness'], 50)
        with self.assertRaises(EsphomeLightBlocked):
            self.dev.undo('brightness')

    def test_refusals_happen_before_anything_is_sent(self):
        for name, value in (('brightness', 150), ('power', 'maybe'), ('firmware', '9.9'), ('ota', 'go'), ('unknown', 1)):
            with self.subTest(name=name), self.assertRaises(EsphomeLightBlocked):
                self.dev.set_reversible(name, value)
        with self.assertRaises(EsphomeLightBlocked):
            self.dev.command('self_destruct')
        self.assertEqual(self.emu.history, [])

    def test_a_device_that_ignores_a_write_is_never_reported_done(self):
        self.emu.drop_writes = True
        self.assertFalse(self.dev.set_reversible('power', 'on')['verified'])

    def test_commands_are_momentary_and_irreversible(self):
        r = self.dev.command('toggle')
        self.assertEqual((r['verified'], r['reversible']), (None, False))
        self.assertEqual(self.emu.state['power'], 'on')

    def test_graph_entry_is_pseudonymized_and_labelled_emulated(self):
        reg = Registry()
        self.assertEqual(ingest_esphome_light(reg, self.dev, b'salt', 'SERIAL-1234')['status'], 'OK')
        snap = reg.snapshot()
        self.assertNotIn('SERIAL-1234', json.dumps(snap))
        self.assertEqual({c['status'] for d in snap['devices'] for c in d['capabilities']}, {'SIMULATED_VERIFIED'})


class TransportShapes(unittest.TestCase):
    def test_power_forms(self):
        for doc, want in (({'state': 'ON'}, 'on'), ({'state': 'off'}, 'off'), ({'state': True}, 'on'),
                          ({'state': False}, 'off'), ({'state': 'On'}, 'on'), ({'state': '0'}, 'off')):
            self.assertEqual(_parse_power(doc), want)
        for doc in ({}, {'state': 'maybe'}, {'state': None}):
            with self.assertRaises(EsphomeLightError):
                _parse_power(doc)

    def test_brightness_scales(self):
        self.assertEqual(_parse_brightness({'brightness': 255}), 100)
        self.assertEqual(_parse_brightness({'brightness': 128}), 50)
        self.assertEqual(_parse_brightness({'brightness': 0}), 0)
        self.assertEqual(_parse_brightness({'brightness_pct': 40}), 40)
        with self.assertRaises(EsphomeLightError):
            _parse_brightness({'state': 'ON'})

    def test_local_hosts_only(self):
        for host in ('192.168.1.10', '10.0.0.2', '172.16.0.1', '127.0.0.1', 'localhost',
                     'lamp.local', 'lamp', 'esphome', 'fe80::1'):
            self.assertTrue(_host_allowed(host), host)
        for host in ('', '8.8.8.8', '1.1.1.1', 'example.com', 'lamp.local.evil.com',
                     'a/b', 'a b', 'user@host', '2001:4860:4860::8888'):
            self.assertFalse(_host_allowed(host), host)
        with self.assertRaises(EsphomeLightBlocked):
            EsphomeLightTransport('8.8.8.8', 'lamp')
        with self.assertRaises(EsphomeLightBlocked):
            EsphomeLightTransport('lamp.local', '../x')


class TransportRoundtrip(unittest.TestCase):
    """The transport against a local fake of the web_server API (loopback HTTP server)."""

    @staticmethod
    def serve(state):
        import threading
        from http.server import BaseHTTPRequestHandler, HTTPServer

        class H(BaseHTTPRequestHandler):
            def log_message(self, *_):
                pass

            def _send(self, doc, code=200):
                body = json.dumps(doc).encode()
                self.send_response(code)
                self.send_header('Content-Type', 'application/json')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def do_GET(self):
                if self.path == '/light/desk':
                    return self._send({'id': 'desk', 'state': state['power'].upper(),
                                       'brightness': int(state['brightness'] * 255 / 100)})
                if self.path == '/device-info':
                    return self._send({'esphome_version': '2026.11.0'})
                return self._send({}, 404)

            def do_POST(self):
                ln = int(self.headers.get('Content-Length') or 0)
                body = json.loads(self.rfile.read(ln) or b'{}') if ln else {}
                if self.path == '/light/desk/turn_on':
                    state['power'] = 'on'
                    if 'brightness' in body:
                        state['brightness'] = int(round(body['brightness'] * 100 / 255))
                elif self.path == '/light/desk/turn_off':
                    state['power'] = 'off'
                elif self.path == '/light/desk/toggle':
                    state['power'] = 'off' if state['power'] == 'on' else 'on'
                else:
                    return self._send({}, 404)
                return self._send({'ok': True})

        srv = HTTPServer(('127.0.0.1', 0), H)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        return srv

    def test_read_write_command_roundtrip(self):
        state = {'power': 'off', 'brightness': 50}
        srv = self.serve(state)
        try:
            dev = EsphomeLight(EsphomeLightTransport('127.0.0.1', 'desk', port=srv.server_port))
            names = {f['name']: f['value'] for f in dev.facts()}
            self.assertEqual((names['power'], names['brightness'], names['firmware']),
                             ('off', 50, '2026.11.0'))
            r = dev.set_reversible('brightness', 80)
            self.assertEqual((r['after'], r['verified']), (80, True))
            self.assertEqual(state, {'power': 'on', 'brightness': 80})
            dev.command('toggle')
            self.assertEqual(state['power'], 'off')
            self.assertTrue(dev.undo('brightness')['exact'])
        finally:
            srv.shutdown()
            srv.server_close()

    def test_garbage_fails_closed(self):
        import threading
        from http.server import BaseHTTPRequestHandler, HTTPServer

        class H(BaseHTTPRequestHandler):
            def log_message(self, *_):
                pass

            def do_GET(self):
                body = b'not json{{'
                self.send_response(200)
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)

        srv = HTTPServer(('127.0.0.1', 0), H)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        try:
            dev = EsphomeLight(EsphomeLightTransport('127.0.0.1', 'desk', port=srv.server_port))
            with self.assertRaises(EsphomeLightError):
                dev.facts()
        finally:
            srv.shutdown()
            srv.server_close()


